import React from 'react';
import { useNavigate } from 'react-router-dom'; // Import useNavigate
import Header from './Header';
import Footer from './Footer';
import './Thankyou.css';  // Make sure you have your CSS file imported
import saree from './saree1.jpg';  // Ensure the image file path is correct

const Thankyou = () => {
    const navigate = useNavigate(); // Initialize useNavigate

    // Handle the Go back Home button click
    const onButtonClick = () => {
        navigate('/HomePage'); // Navigate to HomePage
    };

    return (
        <div class="mainc">
        <Header/>
        <div id="app">
            
  <div class="title">
    <div class="title-inner">
      <div class="cafe">
        <div class="cafe-inner">Thank</div>
      </div>
      <div class="mozart">
        <div class="mozart-inner">Thank</div>
      </div>
    </div>
  </div>

  <div class="image">
    <img src={saree}/>
  </div>
  
</div>
<Footer/>

</div>
    );
};

export default Thankyou;
